import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
def dmax(v):
    m = 0
    while v:
        if v % 10 > m:
            m = v % 10
        v //= 10
    return m
c = 0
for idx in range(n - 1):
    if (dmax(a[idx]) == 7) and (dmax(a[idx + 1]) == 7):
        c += 1
print(c)

